import { test, expect } from '@playwright/test';

test.describe('Share Filtered Search URL', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
    // Wait for the page to load
    await page.waitForLoadState('networkidle');
  });

  test('should generate shareable URL with applied filters', async ({ page }) => {
    // Navigate to search page
    await page.goto('http://localhost:3000/search');

    // Apply first filter
    const categoryFilter = page.getByRole('combobox', { name: /category/i });
    await categoryFilter.click();
    await page.getByRole('option', { name: /electronics/i }).click();

    // Apply second filter
    const priceFilter = page.getByRole('combobox', { name: /price range/i });
    await priceFilter.click();
    await page.getByRole('option', { name: /under \$100/i }).click();

    // Apply third filter
    const ratingFilter = page.getByRole('combobox', { name: /rating/i });
    await ratingFilter.click();
    await page.getByRole('option', { name: /4 stars and up/i }).click();

    // Verify filters are applied
    await expect(page.getByText(/electronics/i)).toBeVisible();
    await expect(page.getByText(/under \$100/i)).toBeVisible();
    await expect(page.getByText(/4 stars and up/i)).toBeVisible();

    // Get the current URL
    const currentUrl = page.url();

    // Verify URL contains filter parameters
    expect(currentUrl).toContain('category=electronics');
    expect(currentUrl).toContain('price=under100');
    expect(currentUrl).toContain('rating=4stars');
  });

  test('should display share button and copy URL to clipboard', async ({ page, context }) => {
    // Navigate to search page
    await page.goto('http://localhost:3000/search');

    // Apply filters
    const categoryFilter = page.getByRole('combobox', { name: /category/i });
    await categoryFilter.click();
    await page.getByRole('option', { name: /books/i }).click();

    const sortFilter = page.getByRole('combobox', { name: /sort by/i });
    await sortFilter.click();
    await page.getByRole('option', { name: /newest/i }).click();

    // Look for share button
    const shareButton = page.getByRole('button', { name: /share/i });
    await expect(shareButton).toBeVisible();

    // Click share button
    await shareButton.click();

    // Verify share dialog appears
    const shareDialog = page.getByRole('dialog', { name: /share search/i });
    await expect(shareDialog).toBeVisible();

    // Verify URL is displayed in the dialog
    const urlDisplay = page.getByRole('textbox', { name: /share url/i });
    await expect(urlDisplay).toBeVisible();

    // Get the URL value
    const shareUrl = await urlDisplay.inputValue();
    expect(shareUrl).toContain('category=books');
    expect(shareUrl).toContain('sort=newest');
  });

  test('should allow copying filtered URL and opening it in new context', async ({ page, context }) => {
    // Navigate to search page
    await page.goto('http://localhost:3000/search');

    // Apply multiple filters
    const categoryFilter = page.getByRole('combobox', { name: /category/i });
    await categoryFilter.click();
    await page.getByRole('option', { name: /clothing/i }).click();

    const sizeFilter = page.getByRole('combobox', { name: /size/i });
    await sizeFilter.click();
    await page.getByRole('option', { name: /medium/i }).click();

    const colorFilter = page.getByRole('combobox', { name: /color/i });
    await colorFilter.click();
    await page.getByRole('option', { name: /blue/i }).click();

    // Get current URL with filters
    const filteredUrl = page.url();

    // Create new page in same context to simulate sharing
    const newPage = await context.newPage();

    // Navigate to the filtered URL
    await newPage.goto(filteredUrl);
    await newPage.waitForLoadState('networkidle');

    // Verify all filters are preserved in the new page
    await expect(newPage.getByText(/clothing/i)).toBeVisible();
    await expect(newPage.getByText(/medium/i)).toBeVisible();
    await expect(newPage.getByText(/blue/i)).toBeVisible();

    // Verify search results are displayed
    const searchResults = newPage.getByRole('region', { name: /search results/i });
    await expect(searchResults).toBeVisible();

    await newPage.close();
  });

  test('should preserve filters when sharing URL with query parameters', async ({ page }) => {
    // Navigate directly with filter parameters
    await page.goto('http://localhost:3000/search?category=home&price=50-200&inStock=true');
    await page.waitForLoadState('networkidle');

    // Verify all filters are applied
    await expect(page.getByText(/home/i)).toBeVisible();
    await expect(page.getByText(/\$50 - \$200/i)).toBeVisible();
    await expect(page.getByText(/in stock/i)).toBeVisible();

    // Verify search results match the filters
    const resultItems = page.getByRole('listitem');
    const count = await resultItems.count();
    expect(count).toBeGreaterThan(0);

    // Click share button
    const shareButton = page.getByRole('button', { name: /share/i });
    await shareButton.click();

    // Verify the shared URL contains all parameters
    const urlDisplay = page.getByRole('textbox', { name: /share url/i });
    const shareUrl = await urlDisplay.inputValue();

    expect(shareUrl).toContain('category=home');
    expect(shareUrl).toContain('price=50-200');
    expect(shareUrl).toContain('inStock=true');
  });

  test('should handle complex filter combinations in shareable URL', async ({ page }) => {
    // Navigate to search page
    await page.goto('http://localhost:3000/search');

    // Apply complex filter combination
    const categoryFilter = page.getByRole('combobox', { name: /category/i });
    await categoryFilter.click();
    await page.getByRole('option', { name: /sports/i }).click();

    const brandFilter = page.getByRole('combobox', { name: /brand/i });
    await brandFilter.click();
    await page.getByRole('option', { name: /nike/i }).click();

    const priceFilter = page.getByRole('combobox', { name: /price range/i });
    await priceFilter.click();
    await page.getByRole('option', { name: /\$100 - \$300/i }).click();

    const ratingFilter = page.getByRole('combobox', { name: /rating/i });
    await ratingFilter.click();
    await page.getByRole('option', { name: /5 stars/i }).click();

    const sortFilter = page.getByRole('combobox', { name: /sort by/i });
    await sortFilter.click();
    await page.getByRole('option', { name: /price: high to low/i }).click();

    // Get the URL
    const complexUrl = page.url();

    // Verify all filter parameters are in URL
    expect(complexUrl).toContain('category=sports');
    expect(complexUrl).toContain('brand=nike');
    expect(complexUrl).toContain('price=100-300');
